def main():
    index,origins,_=k.exclusion_index();review={};pending=[]
    for r in pd.read_csv(k.OUT/'candidate_order.csv').itertuples(index=False):
        path=k.OUT/'api'/f'view_{r.kaggle_id}.json';meta=json.loads(path.read_text()) if path.exists() else {}
        reason,evidence=k.overlap(r.name,index,origins,meta.get('description',''))
        if reason:
            review[r.ref]=dict(status=reason,reason=json.dumps(evidence,ensure_ascii=False));continue
        if meta.get('final_non_rate_limited_failure'):
            review[r.ref]=dict(status='validation_loading_failure',reason=meta['reason'],metadata_sha256=k.file_sha256(path));continue
        if meta.get('acquisition_failure') or not meta:
            pending.append(int(r.position));continue
        if r.position in EXCLUDE:
            status,reason=EXCLUDE[r.position];review[r.ref]=dict(status=status,reason=reason,metadata_sha256=k.file_sha256(path));continue
        if r.position in TARGETS:
            target,anchor,origin=TARGETS[r.position];description=meta['description'];assert anchor in description,(r.position,anchor)
            start=description.index(anchor);end=description.find('\n',start)
            evidence=description[start:end if end!=-1 else len(description)]
            review[r.ref]=dict(status='eligible_for_validation',target=target,target_evidence=evidence,origin_review=origin,
                family=FAMILIES.get(r.position,r.name),metadata_sha256=k.file_sha256(path))
            if r.position in SOURCE_TABLES:
                filename,table_evidence=SOURCE_TABLES[r.position]
                assert table_evidence in description
                review[r.ref].update(source_file=filename,table_evidence=table_evidence)
            if r.position in POSITIONS:review[r.ref].update(POSITIONS[r.position])
            continue
        pending.append(int(r.position))
    atomic_json(k.OUT/'review_draft.json',review)
    atomic_json(k.OUT/'review_pending.json',pending)
    print('Source reviews:',len(review),'pending:',len(pending),'positions:',pending)
    if not pending:
        assert not k.MAN.exists(),'review immutable after manifest'
        atomic_json(k.OUT/'review.json',review)

if __name__=='__main__':main()
